CREATE OR REPLACE FUNCTION better_supabase.bootstrap_islands(args jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not (select better_supabase.session_active()) then
    return jsonb_build_object(
      'session_active', false,
      'authz_version', auth.jwt() -> 'authz_ver',
      'tenant', args ->> 'tenant',
      'data', null
    );
  end if;
  return jsonb_build_object(
    'session_active', true,
    'authz_version', auth.jwt() -> 'authz_ver',
    'tenant', args ->> 'tenant',
    'data', to_jsonb(public.island_counts(args))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.island_counts(args jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'customers', (select count(*) from public.customers as c where c.organization_id = (args ->> 'tenant')::uuid),
    'notes', (select count(*) from public.notes as n where n.organization_id = (args ->> 'tenant')::uuid),
    'contacts', (select count(*) from public.contacts as c where c.organization_id = (args ->> 'tenant')::uuid),
    'tags', (select count(*) from public.tags as t where t.organization_id = (args ->> 'tenant')::uuid),
    'tasks', (select count(*) from public.tasks as t where t.organization_id = (args ->> 'tenant')::uuid)
  );
$function$;

REVOKE ALL ON FUNCTION "public"."island_counts"(jsonb) FROM PUBLIC, "anon";

COMMENT ON FUNCTION "public"."island_counts"(jsonb) IS 'The islands page data: row counts of five tables in the active organization. better_supabase.bootstrap_islands runs it as the caller, so RLS scopes every count.';

GRANT EXECUTE ON FUNCTION "public"."island_counts"(jsonb) TO "authenticated", "service_role";

CREATE OR REPLACE FUNCTION api.bootstrap_islands(args jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select "better_supabase"."bootstrap_islands"($1) $function$;

REVOKE ALL ON FUNCTION "better_supabase"."bootstrap_islands"(jsonb) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "better_supabase"."bootstrap_islands"(jsonb) TO "authenticated";

REVOKE ALL ON FUNCTION "api"."bootstrap_islands"(jsonb) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "api"."bootstrap_islands"(jsonb) TO "authenticated";
